<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>گزارش برگشت از فروش</title><style>body{font-family:Tahoma,Arial,sans-serif;background:#f8fafc;color:#111827}.wrap{max-width:1180px;margin:20px auto;background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px}.actions{text-align:left;margin-bottom:12px}.btn{border:1px solid #334155;border-radius:8px;padding:8px 12px;background:#fff;text-decoration:none;color:#111}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #dbe3ef;padding:7px;text-align:right}th{background:#f1f5f9}@media print{body{background:#fff}.wrap{border:0;margin:0;max-width:none}.actions{display:none}}</style></head><body><div class="wrap"><div class="actions"><button class="btn" onclick="window.print()">چاپ / ذخیره PDF</button><a class="btn" href="{{ route('sales-returns.index', request()->query()) }}">بازگشت</a></div><h2>گزارش برگشت از فروش</h2><table><thead><tr><th>شماره</th><th>تاریخ</th><th>نوع</th><th>مشتری</th><th>مرجع</th><th>اقلام</th><th>مبلغ</th><th>وضعیت</th></tr></thead><tbody>@foreach($documents as $document)<tr><td>{{ $document->document_number }}</td><td>{{ optional($document->created_at)->format('Y/m/d H:i') }}</td><td>{{ $document->sourceTypeLabel() }}</td><td>{{ trim(($document->customer?->first_name ?? '').' '.($document->customer?->last_name ?? '')) ?: '—' }}</td><td>{{ $document->isInternal() ? ($document->invoice?->uuid ?: '—') : ($document->external_invoice_number ?: '—') }}</td><td>{{ $document->items_count }}</td><td>{{ number_format($document->refund_total) }}</td><td>{{ $document->statusLabel() }}</td></tr>@endforeach</tbody></table></div></body></html>
